    fireEvent.click(screen.getByRole('button', { name: 'Close changelog' }));
    expect(onClose).toHaveBeenCalled();
  });
});

#!/usr/bin/env node
/***
 * MARK: generate-changelog.mjs
 * @description Bakes KainBain's default-branch git history into a JSON artifact
 *   for production deploys. Production instances are plain file copies without
 *   `.git`, so `deploy.sh --prod` runs this script at deploy time and ships the
 *   output as `$PROD_DIR/changelog.json`; the API serves it from disk with no
 *   git dependency.
 *
 *   Every git invocation is spawned as an ARGUMENT ARRAY (never a shell
 *   string) per the `api/git.js` no-shell rule, and ref names are validated
 *   before use so a ref starting with `-` can never be consumed as a flag.
 *
 * @example node scripts/generate-changelog.mjs --limit 200 --out changelog.json
 * @example node scripts/generate-changelog.mjs --ref master --limit 5 (prints JSON to stdout)
 ***/

import { spawnSync } from "node:child_process";
import fs from "node:fs";

/***
 * MARK: changelog constants
 * @description Tunables for the baked artifact. DEFAULT_LIMIT bounds file size
 *   and dialog render cost; MAX_BODY_CHARS bounds per-entry bodies (KainBain
 *   auto-commit messages embed whole task prompts, averaging ~3KB — uncapped
 *   bodies push 200 entries to ~675KB, truncated to ~140KB).
 ***/
export const DEFAULT_LIMIT = 200;
export const MAX_BODY_CHARS = 500;
export const FIELD_SEP = "\x00";
export const RECORD_SEP = "\x1e";

// %H sha, %h short, %an author, %ae email, %aI iso date, %s subject, %b body.
const LOG_FORMAT = ["%H", "%h", "%an", "%ae", "%aI", "%s", "%b"].join("%x00") + "%x1e";

/***
 * MARK: isSafeRef
 * @description Validates a git ref name with the same conservative allow-list
 *   as `isValidBranchName` in `api/git.js`: letters, digits, `_`, `-`, `.`,
 *   `/`; must not start with `-`, `/`, `.` (flag injection / hidden refs) and
 *   must not contain `..`, `//`, `@{`, or end with `/`, `.`, `.lock`.
 * @example isSafeRef('master') => true
 * @example isSafeRef('--upload-pack=x') => false
 * @param {string} ref
 * @returns {boolean}
 ***/
export function isSafeRef(ref) {
	if (typeof ref !== "string") return false;
	if (ref.length === 0 || ref.length > 255) return false;
	if (!/^[A-Za-z0-9_./-]+$/.test(ref)) return false;
	if (ref.startsWith("-") || ref.startsWith("/") || ref.startsWith(".")) return false;
	if (ref.endsWith("/") || ref.endsWith(".") || ref.endsWith(".lock")) return false;
	if (ref.includes("..") || ref.includes("//") || ref.includes("@{")) return false;
	return true;
}

/***
 * MARK: runGit
 * @description Runs one git command via argv array (no shell) and returns
 *   stdout. Throws an Error carrying stderr on non-zero exit.
 * @example runGit('/repo', ['rev-parse', '--verify', 'master']) => 'abc...'
 * @param {string} cwd - Working directory for the command.
 * @param {string[]} args - Argument array.
 * @returns {string} Trimmed stdout.
 ***/
export function runGit(cwd, args) {
	const result = spawnSync("git", args, { cwd, encoding: "utf8" });
	if (result.error) {
		throw new Error(`git ${args.join(" ")} failed to start: ${result.error.message}`);
	}
	if (result.status !== 0) {
		const detail = String(result.stderr || result.stdout || "").trim() || "no output";
		throw new Error(`git ${args.join(" ")} failed (exit ${result.status}): ${detail}`);
	}
	return String(result.stdout || "");
}

/***
 * MARK: resolveDefaultBranch
 * @description Resolves which branch to bake: local `master` first, then local
 *   `main`, then the `origin/HEAD` symbolic target. Strict: throws when none
 *   resolves so the caller (deploy.sh) can record a `generation-failed` marker
 *   instead of baking the wrong history. (Deliberately stricter than the
 *   lenient `defaultBranch()` in `api/git.js`, which falls back silently.)
 * @example resolveDefaultBranch('/repo') => 'master'
 * @param {string} cwd - Repository working directory.
 * @returns {string} The resolved branch name.
 ***/
export function resolveDefaultBranch(cwd) {
	for (const name of ["master", "main"]) {
		const probe = spawnSync("git", ["rev-parse", "--verify", "--quiet", `refs/heads/${name}`], {
			cwd,
			encoding: "utf8",
		});
		if (!probe.error && probe.status === 0) return name;
	}
	const head = spawnSync("git", ["symbolic-ref", "refs/remotes/origin/HEAD"], {
		cwd,
		encoding: "utf8",
	});
	if (!head.error && head.status === 0) {
		const branch = String(head.stdout || "").replace("refs/remotes/origin/", "").trim();
		if (isSafeRef(branch)) {
			const verify = spawnSync("git", ["rev-parse", "--verify", "--quiet", branch], {
				cwd,
				encoding: "utf8",
			});
			if (!verify.error && verify.status === 0) return branch;
		}
	}
	throw new Error(
		"Cannot resolve default branch: no local 'master' or 'main' and no refs/remotes/origin/HEAD",
	);
}

/***
 * MARK: admin commit taxonomy
 * @description Bake-time filter so the shipped changelog shows task-merge
 *   history only. Derived from a taxonomy pass over real history (Step 1):
 *   `KainBain:` subjects are automation (auto-commit, converge, merge-latest
 *   sync); `kb/<uuid>` subjects are runner stage-output commits; `Merge
 *   remote-tracking branch` subjects are branch-sync noise. Everything else
 *   (human task work, squash-merge subjects, real merges) is kept.
 * @example isAdminCommitSubject('KainBain: auto-commit pending work') => true
 * @example isAdminCommitSubject('Harden runner log transport') => false
 * @param {string} subject - The commit subject line.
 * @returns {boolean} True when the commit is admin/automation noise to drop.
 ***/
export function isAdminCommitSubject(subject) {
	if (typeof subject !== "string") return true;
	const line = subject.trim();
	if (line.length === 0) return true;
	if (line.startsWith("KainBain:")) return true;
	if (/^kb\/[0-9a-f-]{8,}/i.test(line)) return true;
	if (/^merge remote-tracking branch\b/i.test(line)) return true;
	return false;
}

/***
 * MARK: filterChangelogEntries
 * @description Drops admin/automation entries (see `isAdminCommitSubject`)
 *   from an already-parsed entry list, preserving newest-first order.
 * @example filterChangelogEntries([{ subject: 'KainBain: sync' }]) => []
 * @param {Array<Object>} entries - Parsed changelog entries, newest first.
 * @returns {Array<Object>} The kept entries, newest first.
 ***/
export function filterChangelogEntries(entries) {
	if (!Array.isArray(entries)) return [];
	return entries.filter((entry) => !isAdminCommitSubject(entry?.subject));
}

/***
 * MARK: parseGitLog
 * @description Parses NUL/RS-delimited `git log` output into changelog entries,
 *   newest-first as emitted. Bodies are truncated to MAX_BODY_CHARS with a
 *   `bodyTruncated` flag; malformed records (short fields, empty SHA) are
 *   skipped rather than failing the whole bake.
 * @example parseGitLog(raw) => [{ sha, shortSha, subject, body, bodyTruncated, author, authorEmail, date }]
 * @param {string} raw - Raw stdout from the git log invocation.
 * @returns {Array<Object>} Parsed entries, newest first.
 ***/
export function parseGitLog(raw) {
	if (typeof raw !== "string" || raw.length === 0) return [];
	const entries = [];
	for (const record of raw.split(RECORD_SEP)) {
		if (!record.trim()) continue;
		const fields = record.split(FIELD_SEP);
		if (fields.length < 7) continue;
		const [sha, shortSha, author, authorEmail, date, subject, ...bodyParts] = fields;
		if (!sha || !sha.trim()) continue;
		// A body containing a literal NUL is near-impossible (git truncates
		// messages at NUL), but rejoin defensively so extra separators never
		// drop body text.
		const body = bodyParts.join(FIELD_SEP).replace(/^\n/, "").replace(/\s+$/, "");
		const bodyTruncated = body.length > MAX_BODY_CHARS;
		entries.push({
			sha: sha.trim(),
			shortSha: (shortSha || "").trim(),
			subject: (subject || "").trim(),
			body: bodyTruncated ? body.slice(0, MAX_BODY_CHARS) : body,
			bodyTruncated,
			author: (author || "").trim(),
			authorEmail: (authorEmail || "").trim(),
			date: (date || "").trim(),
		});
	}
	return entries;
}

/***
 * MARK: generateChangelog
 * @description Builds the full changelog artifact for `ref` (resolved via
 *   `resolveDefaultBranch` when omitted): the latest `limit` task-merge
 *   entries plus bake metadata. Admin/automation noise is dropped at bake
 *   time (see `isAdminCommitSubject`), so raw history is paged until `limit`
 *   kept entries are collected or history is exhausted. `totalCount` is the
 *   kept (task-merge) commits visible at bake time; `truncated` is true when
 *   kept history extends beyond `entries`. Pass `filter: false` to bake the
 *   unfiltered history (debugging only).
 * @example generateChangelog({ cwd: '/repo', limit: 5 }) => { branch: 'master', entries: [...] }
 * @param {Object} opts
 * @param {string} [opts.cwd] - Repository working directory (defaults to process.cwd()).
 * @param {string} [opts.ref] - Branch/ref to bake (defaults to resolved default branch).
 * @param {number} [opts.limit] - Max entries to bake (defaults to DEFAULT_LIMIT).
 * @param {boolean} [opts.filter] - Drop admin commits (defaults to true).
 * @returns {Object} The changelog artifact.
 ***/
export function generateChangelog({ cwd = process.cwd(), ref, limit = DEFAULT_LIMIT, filter = true } = {}) {
	const count = Number(limit);
	if (!Number.isInteger(count) || count < 1) {
		throw new Error(`generateChangelog requires a positive integer limit, got ${String(limit)}`);
	}
	const branch = ref || resolveDefaultBranch(cwd);
	if (!isSafeRef(branch)) {
		throw new Error(`Refusing to bake unsafe ref ${String(branch)}`);
	}
	const keep = (entry) => !filter || !isAdminCommitSubject(entry?.subject);
	// Page the raw log until `count` kept entries are collected: noise-heavy
	// stretches would otherwise bake a short artifact. Each page advances
	// `--skip` past already-seen raw commits; at most ten pages bound the
	// deploy-time cost, and a short page ends history.
	const kept = [];
	let skip = 0;
	for (let page = 0; page < 10 && kept.length < count; page += 1) {
		const raw = runGit(cwd, [
			"log",
			branch,
			"-n",
			String(count),
			"--skip",
			String(skip),
			`--format=${LOG_FORMAT}`,
		]);
		const parsed = parseGitLog(raw);
		if (parsed.length === 0) break;
		skip += parsed.length;
		for (const entry of parsed) {
			if (keep(entry)) kept.push(entry);
			if (kept.length >= count) break;
		}
		if (parsed.length < count) break;
	}
	const entries = kept.slice(0, count);
	let totalCount;
	if (!filter) {
		const totalRaw = runGit(cwd, ["rev-list", "--count", branch]).trim();
		totalCount = Number.parseInt(totalRaw, 10);
		if (!Number.isInteger(totalCount) || totalCount < 0) {
			throw new Error(`Unparseable rev-list count for '${branch}': ${totalRaw}`);
		}
	} else {
		// Honest kept-commit count: subjects only (no bodies), one pass.
		const subjects = runGit(cwd, ["log", branch, "--format=%s"]).split("\n");
		totalCount = subjects.filter((subject) => !isAdminCommitSubject(subject)).length;
	}
	const commit = runGit(cwd, ["rev-parse", branch]).trim();
	return {
		generatedAt: new Date().toISOString(),
		branch,
		commit,
		totalCount,
		truncated: totalCount > entries.length,
		limit: count,
		entries,
	};
}

function printUsageAndExit(exitCode) {
	const usage = [
		"Usage: node scripts/generate-changelog.mjs [--ref <branch>] [--limit <n>] [--out <file>] [--cwd <dir>] [--no-filter]",
		"",
		"  --ref    Branch to bake (default: resolved default branch, master > main > origin/HEAD).",
		`  --limit  Max entries to bake (default: ${DEFAULT_LIMIT}).`,
		"  --out    Write JSON to <file> instead of stdout.",
		"  --cwd    Repository directory (default: current directory).",
		"  --no-filter  Bake unfiltered history (debugging only; default drops admin commits).",
	].join("\n");
	const stream = exitCode === 0 ? process.stdout : process.stderr;
	stream.write(`${usage}\n`);
	process.exit(exitCode);
}

/***
 * MARK: changelog CLI
 * @description `node scripts/generate-changelog.mjs --ref <branch> --limit 200
 *   --out <file>`: argv-parsed, non-zero exit with clear stderr when the ref is
 *   missing or git fails. Skipped on import so tests can use the pure exports.
 ***/
const invokedAsScript =
	typeof process.argv[1] === "string" && import.meta.url.endsWith(process.argv[1].split("/").pop());
if (invokedAsScript) {
	const args = process.argv.slice(2);
	let ref;
	let limit = DEFAULT_LIMIT;
	let out;
	let cwd = process.cwd();
	let filter = true;
	try {
		for (let i = 0; i < args.length; i += 1) {
			const arg = args[i];
			if (arg === "--help" || arg === "-h") printUsageAndExit(0);
			else if (arg === "--ref") ref = args[(i += 1)];
			else if (arg === "--limit") limit = Number(args[(i += 1)]);
			else if (arg === "--out") out = args[(i += 1)];
			else if (arg === "--cwd") cwd = args[(i += 1)];
			else if (arg === "--no-filter") filter = false;
			else throw new Error(`Unknown argument: ${arg}`);
		}
		if (ref !== undefined && !isSafeRef(ref)) {
			throw new Error(`Refusing to bake unsafe ref ${String(ref)}`);
		}
		const artifact = generateChangelog({ cwd, ref, limit, filter });
		const json = `${JSON.stringify(artifact, null, 2)}\n`;
		if (out) {
			fs.writeFileSync(out, json, "utf8");
		} else {
			process.stdout.write(json);
		}
	} catch (err) {
		process.stderr.write(`generate-changelog: ${err.message}\n`);
		process.exit(1);
	}
}

import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";

import {
	DEFAULT_LIMIT,
	FIELD_SEP,
	RECORD_SEP,
	filterChangelogEntries,
	generateChangelog,
	isAdminCommitSubject,
	isSafeRef,
	parseGitLog,
} from "../scripts/generate-changelog.mjs";

/***
 * MARK: generate-changelog tests
 * @description Bake-time changelog filter tests (task-merge history for the
 *   Now Playing bar `#buildhash` dialog): admin/automation subjects are
 *   dropped, human task work survives, newest-first order is preserved, and
 *   `generateChangelog` pages past noise to fill its limit against a real
 *   throwaway git repo.
 * @example run `node --test tests/generate-changelog.test.mjs`
 ***/

function rawEntry({ sha, short, author, email, date, subject, body }) {
	return (
		[sha, short, author, email, date, subject, body ?? ""].join(FIELD_SEP) + RECORD_SEP
	);
}

describe("isAdminCommitSubject", () => {
	it("drops KainBain automation sync subjects", () => {
		assert.equal(isAdminCommitSubject("KainBain: auto-commit pending work on 'main'"), true);
		assert.equal(
			isAdminCommitSubject("KainBain: merge latest main into 'kb/abc' (sync task branch)"),
			true,
		);
	});

	it("drops runner stage-output subjects", () => {
		assert.equal(
			isAdminCommitSubject("kb/91257d62-f181-4ee0-ab91-f00188221c78 3: Runner local-alpha stage output"),
			true,
		);
		assert.equal(isAdminCommitSubject("kb/2b2c7858-604c-42dc-8a16-6b0f97210a3a 5: Runner output"), true);
	});

	it("drops merge remote-tracking noise case-insensitively", () => {
		assert.equal(
			isAdminCommitSubject("Merge remote-tracking branch 'origin/main' into kb/abc"),
			true,
		);
		assert.equal(isAdminCommitSubject("merge remote-tracking branch 'origin/main'"), true);
	});

	it("keeps human task work and real merges", () => {
		for (const subject of [
			"Harden runner log transport and live fan-out (stage cleanup)",
			"Squash-merge task branches with task-details commits",
			"CI: publish/update/install split with asymmetric updates and ad-site sync",
			"docs(research): human-graded finetune data flywheel spike",
			"Merge main: keep model-reporting fix alongside CI workdir changes",
			"Fix exit-78 on publish stages: worktree guard by path",
		]) {
			assert.equal(isAdminCommitSubject(subject), false, subject);
		}
	});

	it("treats empty and non-string subjects as admin (never bake a blank row)", () => {
		assert.equal(isAdminCommitSubject(""), true);
		assert.equal(isAdminCommitSubject("   "), true);
		assert.equal(isAdminCommitSubject(null), true);
		assert.equal(isAdminCommitSubject(undefined), true);
	});

	it("does not confuse lookalike prefixes with admin markers", () => {
		assert.equal(isAdminCommitSubject("KainBainish: not the automation prefix"), false);
		assert.equal(isAdminCommitSubject("kb-notes: a human note, no uuid"), false);
		assert.equal(isAdminCommitSubject("Merge branch 'feature' into main"), false);
	});
});

describe("filterChangelogEntries", () => {
	it("drops admin entries and preserves newest-first order", () => {
		const entries = [
			{ sha: "c3", subject: "Newest human fix" },
			{ sha: "c2", subject: "KainBain: auto-commit engine snapshots" },
			{ sha: "c1", subject: "kb/aaaa1111-bbbb-4ccc-8ddd-eeeeeeeeeeee 3: Runner stage output" },
			{ sha: "c0", subject: "Older human fix" },
		];
		assert.deepEqual(
			filterChangelogEntries(entries).map((entry) => entry.sha),
			["c3", "c0"],
		);
	});

	it("tolerates non-array and malformed input", () => {
		assert.deepEqual(filterChangelogEntries(null), []);
		assert.deepEqual(filterChangelogEntries([{ sha: "x" }]), []);
	});
});

describe("parseGitLog plus filter round-trip", () => {
	it("parses the baked format and filters to task-merge history", () => {
		const raw =
			rawEntry({
				sha: "aaa",
				short: "aaa",
				author: "Dev",
				email: "d@e.c",
				date: "2026-10-01T00:00:00Z",
				subject: "Human fix",
			}) +
			rawEntry({
				sha: "bbb",
				short: "bbb",
				author: "Runner",
				email: "r@e.c",
				date: "2026-09-30T00:00:00Z",
				subject: "KainBain: auto-commit pending work",
			});
		const parsed = parseGitLog(raw);
		assert.equal(parsed.length, 2);
		assert.deepEqual(
			filterChangelogEntries(parsed).map((entry) => entry.sha),
			["aaa"],
		);
	});
});

describe("generateChangelog against a throwaway repo", () => {
	function makeRepo(subjects) {
		const dir = fs.mkdtempSync(path.join(os.tmpdir(), "kainbain-changelog-test-"));
		execFileSync("git", ["init", "-b", "master"], { cwd: dir });
		execFileSync("git", ["config", "user.email", "test@example.com"], { cwd: dir });
		execFileSync("git", ["config", "user.name", "Test"], { cwd: dir });
		for (const subject of subjects) {
			fs.writeFileSync(path.join(dir, "file.txt"), `${subject}\n`, "utf8");
			execFileSync("git", ["add", "file.txt"], { cwd: dir });
			execFileSync("git", ["commit", "-m", subject, "--allow-empty"], { cwd: dir });
		}
		return dir;
	}

	it("pages past noise to fill the limit and counts only kept commits", () => {
		const dir = makeRepo([
			"Human fix one",
			"KainBain: auto-commit pending work on 'main'",
			"kb/11111111-2222-4aaa-8bbb-cccccccccccc 3: Runner stage output",
			"Human fix two",
			"Merge remote-tracking branch 'origin/main'",
		]);
		try {
			const artifact = generateChangelog({ cwd: dir, ref: "master", limit: 2 });
			assert.equal(artifact.branch, "master");
			assert.deepEqual(
				artifact.entries.map((entry) => entry.subject),
				["Human fix two", "Human fix one"],
			);
			assert.equal(artifact.totalCount, 2);
			assert.equal(artifact.truncated, false);
			assert.match(artifact.commit, /^[0-9a-f]{40}$/);
		} finally {
			fs.rmSync(dir, { recursive: true, force: true });
		}
	});

	it("marks truncation when kept history exceeds the limit", () => {
		const dir = makeRepo(["Human fix one", "Human fix two", "Human fix three"]);
		try {
			const artifact = generateChangelog({ cwd: dir, ref: "master", limit: 2 });
			assert.equal(artifact.entries.length, 2);
			assert.equal(artifact.totalCount, 3);
			assert.equal(artifact.truncated, true);
		} finally {
			fs.rmSync(dir, { recursive: true, force: true });
		}
	});

	it("supports an unfiltered bake for debugging", () => {
		const dir = makeRepo(["Human fix one", "KainBain: auto-commit pending work on 'main'"]);
		try {
			const artifact = generateChangelog({ cwd: dir, ref: "master", limit: 5, filter: false });
			assert.equal(artifact.entries.length, 2);
			assert.equal(artifact.totalCount, 2);
		} finally {
			fs.rmSync(dir, { recursive: true, force: true });
		}
	});

	it("still validates refs and limits", () => {
		assert.throws(() => generateChangelog({ cwd: ".", ref: "--upload-pack=x", limit: 5 }));
		assert.throws(() => generateChangelog({ cwd: ".", ref: "master", limit: 0 }));
		assert.equal(isSafeRef("master"), true);
		assert.equal(DEFAULT_LIMIT, 200);
	});
});

/* eslint-disable security/detect-non-literal-fs-filename -- temp-dir fixtures only, never user input */
import { describe, it, expect, beforeEach, afterEach } from "vitest";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync, spawnSync } from "node:child_process";

/***
 * MARK: Changelog generator tests
 * @description Covers `scripts/generate-changelog.mjs` (the deploy-time baker
 *   for `$PROD_DIR/changelog.json`). The suite lives in `api/` rather than
 *   next to the script because the repo root has no vitest runner — only
 *   `api/` and `frontend/` suites run under `npm run test:unit`. Real-git
 *   cases use throwaway temp repos (never the KainBain repo) and skip when git
 *   is unavailable, mirroring `api/git.integration.test.js`.
 * @example run `npm run test --prefix api`
 ***/
const {
	parseGitLog,
	isSafeRef,
	resolveDefaultBranch,
	generateChangelog,
	DEFAULT_LIMIT,
	MAX_BODY_CHARS,
	FIELD_SEP,
	RECORD_SEP,
} = await import("../scripts/generate-changelog.mjs");

let gitAvailable = true;
try {
	execFileSync("git", ["--version"], { stdio: "ignore" });
} catch {
	gitAvailable = false;
}

function run(cwd, ...args) {
	return execFileSync("git", args, { cwd, stdio: ["ignore", "pipe", "pipe"] }).toString();
}

function initRepo(cwd, { initialBranch = "master" } = {}) {
	fs.mkdirSync(cwd, { recursive: true });
	run(cwd, "init", "-b", initialBranch);
	run(cwd, "config", "user.email", "kainbain-test@example.com");
	run(cwd, "config", "user.name", "KainBain Test");
	return cwd;
}

function commitFile(cwd, name, body, message) {
	fs.writeFileSync(path.join(cwd, name), body);
	run(cwd, "add", "-A");
	run(cwd, "commit", "--allow-empty-message", "-m", message);
}

describe("parseGitLog", () => {
	it("parses a golden fixture newest-first, incl. unicode, pipes and quotes", () => {
		const rec = (fields) => fields.join(FIELD_SEP);
		const raw =
			rec([
				"aaa111",
				"aaa111",
				"Tést Author",
				"test@example.com",
				"2026-09-30T08:00:00+01:00",
				"Fix pipes | and \"quotes\" in subject",
				"Line one\nLine two — unicode ✓",
			]) +
			RECORD_SEP +
			"\n" +
			rec([
				"bbb222",
				"bbb222",
				"Second",
				"second@example.com",
				"2026-09-29T08:00:00+01:00",
				"Empty body commit",
				"",
			]) +
			RECORD_SEP +
			"\n";
		const entries = parseGitLog(raw);
		expect(entries).toHaveLength(2);
		expect(entries[0]).toEqual({
			sha: "aaa111",
			shortSha: "aaa111",
			subject: 'Fix pipes | and "quotes" in subject',
			body: "Line one\nLine two — unicode ✓",
			bodyTruncated: false,
			author: "Tést Author",
			authorEmail: "test@example.com",
			date: "2026-09-30T08:00:00+01:00",
		});
		expect(entries[1].body).toBe("");
		expect(entries[1].bodyTruncated).toBe(false);
	});

	it("truncates long bodies and flags them", () => {
		const longBody = `x`.repeat(MAX_BODY_CHARS + 100);
		const raw =
			["ccc333", "ccc333", "A", "a@e.c", "2026-09-30", "Big", longBody].join(FIELD_SEP) +
			RECORD_SEP;
		const [entry] = parseGitLog(raw);
		expect(entry.body).toHaveLength(MAX_BODY_CHARS);
		expect(entry.bodyTruncated).toBe(true);
	});

	it("skips malformed records and returns [] for empty input", () => {
		expect(parseGitLog("")).toEqual([]);
		expect(parseGitLog(null)).toEqual([]);
		const raw = `short${FIELD_SEP}record${RECORD_SEP}\n${FIELD_SEP}${RECORD_SEP}`;
		expect(parseGitLog(raw)).toEqual([]);
	});
});

describe("isSafeRef", () => {
	it.each(["master", "main", "kb/task-1", "origin/master", "v1.2.3"])(
		"accepts %s",
		(ref) => {
			expect(isSafeRef(ref)).toBe(true);
		},
	);
	it.each(["--upload-pack=x", "-b", "../escape", "a//b", "a@{b", "", ".hidden", "a.lock", 42, null])(
		"rejects %s",
		(ref) => {
			expect(isSafeRef(ref)).toBe(false);
		},
	);
});

describe("resolveDefaultBranch", () => {
	if (!gitAvailable) {
		it.skip("skipped: git is not available", () => {});
		return;
	}
	let tmp;
	beforeEach(() => {
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "changelog-branch-"));
	});
	afterEach(() => {
		fs.rmSync(tmp, { recursive: true, force: true });
	});

	it("resolves master when present", () => {
		initRepo(tmp, { initialBranch: "master" });
		commitFile(tmp, "a.txt", "a", "init");
		expect(resolveDefaultBranch(tmp)).toBe("master");
	});

	it("resolves main when master is absent", () => {
		initRepo(tmp, { initialBranch: "main" });
		commitFile(tmp, "a.txt", "a", "init");
		expect(resolveDefaultBranch(tmp)).toBe("main");
	});

	it("prefers master when both exist", () => {
		initRepo(tmp, { initialBranch: "master" });
		commitFile(tmp, "a.txt", "a", "init");
		run(tmp, "branch", "main");
		expect(resolveDefaultBranch(tmp)).toBe("master");
	});

	it("throws when neither master, main, nor origin/HEAD exists", () => {
		initRepo(tmp, { initialBranch: "trunk" });
		commitFile(tmp, "a.txt", "a", "init");
		expect(() => resolveDefaultBranch(tmp)).toThrow("Cannot resolve default branch");
	});
});

describe("generateChangelog", () => {
	if (!gitAvailable) {
		it.skip("skipped: git is not available", () => {});
		return;
	}
	let tmp;
	beforeEach(() => {
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "changelog-gen-"));
		initRepo(tmp, { initialBranch: "master" });
		commitFile(tmp, "a.txt", "a", "first\n\nFirst body.");
		commitFile(tmp, "b.txt", "b", "second");
		commitFile(tmp, "c.txt", "c", "third");
	});
	afterEach(() => {
		fs.rmSync(tmp, { recursive: true, force: true });
	});

	it("bakes newest-first entries with metadata and truncation flags", () => {
		const artifact = generateChangelog({ cwd: tmp, limit: 2 });
		expect(artifact.branch).toBe("master");
		expect(artifact.limit).toBe(2);
		expect(artifact.totalCount).toBe(3);
		expect(artifact.truncated).toBe(true);
		expect(artifact.commit).toMatch(/^[0-9a-f]{40}$/);
		expect(Date.parse(artifact.generatedAt)).not.toBeNaN();
		expect(artifact.entries.map((e) => e.subject)).toEqual(["third", "second"]);
		expect(artifact.entries[0].shortSha).toHaveLength(7);
	});

	it("reports truncated:false when history fits the limit", () => {
		const artifact = generateChangelog({ cwd: tmp, limit: 10 });
		expect(artifact.totalCount).toBe(3);
		expect(artifact.truncated).toBe(false);
		expect(artifact.entries).toHaveLength(3);
	});

	it("uses DEFAULT_LIMIT when no limit is given", () => {
		const artifact = generateChangelog({ cwd: tmp });
		expect(artifact.limit).toBe(DEFAULT_LIMIT);
		expect(artifact.entries).toHaveLength(3);
	});

	it("rejects invalid limits and unsafe refs", () => {
		expect(() => generateChangelog({ cwd: tmp, limit: 0 })).toThrow("positive integer");
		expect(() => generateChangelog({ cwd: tmp, ref: "--flag" })).toThrow("unsafe ref");
	});

	it("throws a clear error for a missing ref", () => {
		expect(() => generateChangelog({ cwd: tmp, ref: "nope" })).toThrow("failed");
	});

	it("round-trips through DeployManager.readChangelog shape validation", async () => {
		const { DeployManager } = await import("./deployManager.js");
		const prodDir = fs.mkdtempSync(path.join(os.tmpdir(), "changelog-prod-"));
		try {
			const artifact = generateChangelog({ cwd: tmp, limit: 2 });
			fs.writeFileSync(path.join(prodDir, "changelog.json"), JSON.stringify(artifact));
			const manager = new DeployManager({ repoRoot: tmp, deployDir: tmp, prodDir });
			const read = manager.readChangelog();
			expect(read.branch).toBe("master");
			expect(read.totalCount).toBe(3);
			expect(read.entries.map((e) => e.subject)).toEqual(["third", "second"]);
		} finally {
			fs.rmSync(prodDir, { recursive: true, force: true });
		}
	});
});

describe("generate-changelog CLI", () => {
	if (!gitAvailable) {
		it.skip("skipped: git is not available", () => {});
		return;
	}
	let tmp;
	beforeEach(() => {
		tmp = fs.mkdtempSync(path.join(os.tmpdir(), "changelog-cli-"));
		initRepo(tmp, { initialBranch: "master" });
		commitFile(tmp, "a.txt", "a", "cli commit");
	});
	afterEach(() => {
		fs.rmSync(tmp, { recursive: true, force: true });
	});

	const scriptPath = path.resolve(import.meta.dirname, "../scripts/generate-changelog.mjs");

	it("writes a valid artifact file with --out", () => {
		const out = path.join(tmp, "changelog.json");
		const result = spawnSync(
			process.execPath,
			[scriptPath, "--cwd", tmp, "--limit", "5", "--out", out],
			{ encoding: "utf8" },
		);
		expect(result.status).toBe(0);
		const artifact = JSON.parse(fs.readFileSync(out, "utf8"));
		expect(artifact.branch).toBe("master");
		expect(artifact.entries).toHaveLength(1);
		expect(artifact.entries[0].subject).toBe("cli commit");
	});

	it("prints JSON to stdout without --out", () => {
		const result = spawnSync(process.execPath, [scriptPath, "--cwd", tmp, "--limit", "5"], {
			encoding: "utf8",
		});
		expect(result.status).toBe(0);
		const artifact = JSON.parse(result.stdout);
		expect(artifact.totalCount).toBe(1);
	});

	it("exits non-zero with a clear stderr for a missing ref", () => {
		const result = spawnSync(
			process.execPath,
			[scriptPath, "--cwd", tmp, "--ref", "missing-branch"],
			{ encoding: "utf8" },
		);
		expect(result.status).not.toBe(0);
		expect(result.stderr).toContain("generate-changelog:");
	});
});

